import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope):
    node = node_by_title(doc, scope)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {col: cell for col, cell in zip(cols, row)}) for i, row in enumerate(rows)]

def entities(doc, scope) -> list:
    prod_node = None
    for node in scope_nodes(doc, scope):
        if node["title"] == f"{scope}: Products":
            prod_node = node
            break
    if not prod_node:
        return []

    entities_list = []
    for row_idx, row in table_rows(prod_node):
        p_id = row["product"]
        entities_list.append({"id": p_id, "description": p_id})
    return entities_list

def recorded_end(doc, scope) -> float or None:
    nodes = scope_nodes(doc, scope)
    max_day = -1.0

    # Check daily ledger
    ledger_node = next((n for n in nodes if n["title"] == f"{scope}: Daily ledger"), None)
    if ledger_node:
        for row_idx, row in table_rows(ledger_node):
            try:
                day = float(row["day"])
                if day > max_day:
                    max_day = day
            except (ValueError, KeyError):
                continue

    # Check order book tables
    for node in nodes:
        if node["kind"] == "table" and "Order book" in node["title"]:
            for row_idx, row in table_rows(node):
                try:
                    day = float(row["day"])
                    if day > max_day:
                        max_day = day
                except (ValueError, KeyError):
                    continue

    return max_day if max_day != -1.0 else None

